    depot = get_first(["depot", "depot_id", "depot_index"], 0)

    coord_map = {}
    if type(coords) is dict:
        coord_map = coords
    elif type(coords) is list:
        i = 0
        while i < len(coords):
            coord_map[i] = coords[i]
            i += 1

    demand_map = {}
    if type(demands) is dict:
        demand_map = demands
    elif type(demands) is list:
        i = 0
        while i < len(demands):
            demand_map[i] = demands[i]
            i += 1

    if type(instance) is dict and "customers" in instance:
        customers = list(instance["customers"])
    else:
        if coord_map:
            customers = [i for i in coord_map.keys() if i != depot]
        elif demand_map:
            customers = [i for i in demand_map.keys() if i != depot]
        else:
            n = get_first(["n", "num_nodes", "size"], 0)
            try:
                n = int(n)
            except Exception:
                n = 0
            customers = [i for i in range(n) if i != depot]

    customers = sorted(set(customers))

    def to_float(x, default=0.0):
        try:
            return float(x)
        except Exception:
            return default

    def demand_of(i):
        return to_float(demand_map.get(i, 0.0), 0.0)

    def coord_of(i):
        return coord_map.get(i, None)

    def dist(a, b):
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is None or cb is None:
            return 0.0
        try:
            ax, ay = ca[0], ca[1]
            bx, by = cb[0], cb[1]
            dx = ax - bx
            dy = ay - by
            return (dx * dx + dy * dy) ** 0.5
        except Exception:
            return 0.0

    total_demand = 0.0
    for i in customers:
        total_demand += demand_of(i)

    if capacity is None:
        capacity = total_demand + 1.0
    capacity = to_float(capacity, total_demand + 1.0)
    if capacity <= 0:
        capacity = total_demand + 1.0

    depot_coord = coord_of(depot)

    def polar_key(i):
        c = coord_of(i)
        if c is None or depot_coord is None:
            return (0, i)
        try:
            dx = c[0] - depot_coord[0]
            dy = c[1] - depot_coord[1]
            if dx >= 0 and dy >= 0:
                quad = 0
            elif dx < 0 and dy >= 0:
                quad = 1
            elif dx < 0 and dy < 0:
                quad = 2
            else:
                quad = 3
            denom = abs(dx) + abs(dy) + 1e-12
            return (quad, abs(dy) / denom, dist(depot, i), i)
        except Exception:
            return (0, i)

    ordered = sorted(customers, key=polar_key)

    unassigned = set(customers)
    routes = []

    def best_seed_from(pool):
        best = None
        best_key = None
        for i in pool:
            d = demand_of(i)
            if d <= capacity:
                key = (dist(depot, i), d, i)
            else:
                key = (1e18 + d, d, i)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    while unassigned:
        route = []
        load = 0.0

        seed = None
        for i in ordered:
            if i in unassigned and load + demand_of(i) <= capacity:
                seed = i
                break
        if seed is None:
            seed = best_seed_from(unassigned)

        route.append(seed)
        unassigned.remove(seed)
        load += demand_of(seed)
        current = seed

        while True:
            best = None
            best_key = None
            for j in unassigned:
                dj = demand_of(j)
                if load + dj <= capacity:
                    key = (dist(current, j), dist(depot, j), dj, j)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = j
            if best is None:
                break
            route.append(best)
            unassigned.remove(best)
            load += demand_of(best)
            current = best

        routes.append(route)

    # Repair / improvement: relocate small customers from heavy routes to reduce fragmentation.
    # Deterministic first-fit merge attempts.
    changed = True
    while changed:
        changed = False
        i = 0
        while i < len(routes):
            if len(routes[i]) == 0:
                i += 1
                continue
            j = 0
            while j < len(routes):
                if i != j and len(routes[i]) > 0:
                    load_i = 0.0
                    load_j = 0.0
                    for x in routes[i]:
                        load_i += demand_of(x)
                    for x in routes[j]:
                        load_j += demand_of(x)
                    if load_i + load_j <= capacity and len(routes[i]) + len(routes[j]) <= len(customers):
                        # Merge if it does not create too many additional turns.
                        merged = routes[i] + routes[j]
                        old_cost = 0.0
                        if depot_coord is not None:
                            prev = depot
                            for x in routes[i]:
                                old_cost += dist(prev, x)
                                prev = x
                            old_cost += dist(prev, depot)
                            prev = depot
                            for x in routes[j]:
                                old_cost += dist(prev, x)
                                prev = x
                            old_cost += dist(prev, depot)
                            new_cost = 0.0
                            prev = depot
                            for x in merged:
                                new_cost += dist(prev, x)
                                prev = x
                            new_cost += dist(prev, depot)
                            if new_cost <= old_cost + 1e-9:
                                routes[i] = merged
                                del routes[j]
                                changed = True
                                break
                        else:
                            routes[i] = merged
                            del routes[j]
                            changed = True
                            break
                j += 1
            if changed:
                break
            i += 1

    # Final sanity: ensure all customers exactly once, no depot in routes.
    seen = {}
    final_routes = []
    for r in routes:
        rr = []
        for x in r:
            if x != depot and x not in seen:
                seen[x] = 1
                rr.append(x)
        if rr:
            final_routes.append(rr)

    missing = [i for i in customers if i not in seen]
    if missing:
        missing = sorted(missing, key=polar_key)
        for m in missing:
            placed = False
            best_idx = None
            best_key = None
            dm = demand_of(m)
            for idx in range(len(final_routes)):
                load = 0.0
                for x in final_routes[idx]:
                    load += demand_of(x)
                if load + dm <= capacity:
                    route = final_routes[idx]
                    prev = depot
                    old_cost = 0.0
                    for x in route:
                        old_cost += dist(prev, x)
                        prev = x
                    old_cost += dist(prev, depot)

                    best_pos = len(route)
                    best_ins = None
                    p = 0
                    while p <= len(route):
                        new_cost = 0.0
                        prev = depot
                        k = 0
                        while k < p:
                            new_cost += dist(prev, route[k])
                            prev = route[k]
                            k += 1
                        new_cost += dist(prev, m)
                        prev = m
                        k = p
                        while k < len(route):
                            new_cost += dist(prev, route[k])
                            prev = route[k]
                            k += 1
                        new_cost += dist(prev, depot)
                        delta = new_cost - old_cost
                        key = (delta, p)
                        if best_ins is None or key < best_ins:
                            best_ins = key
                            best_pos = p
                        p += 1
                    key = (best_ins[0], len(route), idx)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_idx = (idx, best_pos)
            if best_idx is None:
                final_routes.append([m])
            else:
                idx, pos = best_idx
                final_routes[idx] = final_routes[idx][:pos] + [m] + final_routes[idx][pos:]

    return final_routes
